def balanced_orientation(edges, vertices):
    """Process each connected component separately."""
    adj = defaultdict(list)
    for u,v in edges:
        adj[u].append(v); adj[v].append(u)
    # find connected components
    visited=set()
    comps=[]
    for v in vertices:
        if v not in visited:
            comp=[]; stack=[v]
            while stack:
                w=stack.pop()
                if w in visited: continue
                visited.add(w); comp.append(w)
                for u in adj[w]:
                    if u not in visited: stack.append(u)
            comps.append(comp)

    oriented=set()  # (a,b) means a->b
    for comp in comps:
        comp_set=set(comp)
        deg=defaultdict(int)
        comp_edges=[]
        for u,v in edges:
            if u in comp_set:
                comp_edges.append((u,v))
                deg[u]+=1; deg[v]+=1
        odd=[v for v in comp if deg[v]%2==1]
        if len(comp_edges)==0: continue
        # add dummy
        dummy='__DUMMY__'
        adj2=defaultdict(list)
        for u,v in comp_edges:
            adj2[u].append(v); adj2[v].append(u)
        for v in odd:
            adj2[v].append(dummy); adj2[dummy].append(v)
        allv=list(comp)+[dummy]
        # check all even
        for v in allv:
            assert len(adj2[v])%2==0, f"{v} has odd degree {len(adj2[v])}"
        # Hierholzer
        loc={v:list(adj2[v]) for v in allv}
        stack=[dummy]; circuit=[]
        while stack:
            v=stack[-1]
            if loc[v]:
                u=loc[v].pop()
                loc[u].remove(v)
                stack.append(u)
            else:
                circuit.append(stack.pop())
        for i in range(len(circuit)-1):
            oriented.add((circuit[i],circuit[i+1]))

    result={}
    for u,v in edges:
        if (u,v) in oriented: result[(u,v)]=+1
        elif (v,u) in oriented: result[(u,v)]=-1
        else: result[(u,v)]='MISSING'
    return result

